insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 4, 'E Moisés entalhou duas tábuas de pedra como as primeiras; e levantou-se pela manhã, e subiu ao monte de Sinai, como lhe mandou o SENHOR, e levou em sua mão as duas tábuas de pedra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 5, 'E o SENHOR desceu na nuvem, e esteve ali com ele, proclamando o nome do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 6, 'E passando o SENHOR por diante dele, proclamou: SENHOR, SENHOR, forte, misericordioso, e piedoso; tardio para a ira, e grande em benignidade e verdade;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 7, 'Que guarda a misericórdia em milhares, que perdoa a iniquidade, a rebelião, e o pecado, e que de nenhum modo justificará ao malvado; que visita a iniquidade dos pais sobre os filhos e sobre os filhos dos filhos, sobre os de terceira, e quarta gerações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 8, 'Então Moisés, apressando-se, baixou a cabeça até o chão e encurvou-se;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 9, 'E disse: Se agora, Senhor, achei favor em teus olhos, vá agora o Senhor em meio de nós; porque este é povo de dura cerviz; e perdoa nossa iniquidade e nosso pecado, e possui-nos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 10, 'E ele disse: Eis que, eu faço concerto diante de todo o teu povo: farei maravilhas que não foram feitas em toda a terra, nem em nação alguma; e verá todo o povo em meio do qual estás tu, a obra do SENHOR; porque será coisa terrível a que eu farei contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 11, 'Guarda o que eu te mando hoje; eis que eu expulso de diante de tua presença aos amorreus, e aos cananeus, e aos heteus, e aos perizeus, e aos heveus, e aos jebuseus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 12, 'Guarda-te que não faças aliança com os moradores da terra de onde hás de entrar, para que não sejam por tropeço em meio de ti:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 13, 'Mas derrubareis seus altares, e quebrareis suas estátuas, e cortareis seus bosques:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 14, 'Porque não te hás de inclinar a deus alheio; que o SENHOR, cujo nome é zeloso, Deus zeloso é.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 15, 'Portanto não farás aliança com os moradores daquela terra; pois senão fornicarão após seus deuses, e sacrificarão a seus deuses, e te chamarão, e comerás de seus sacrifícios;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 16, 'Ou, se tomarem de suas filhas para teus filhos, e fornicarem suas filhas após seus deuses, farão também fornicar a teus filhos atrás dos deuses delas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 17, 'Não farás deuses de fundição para ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 18, 'A festa dos pães ázimos guardarás: sete dias comerás sem levedar, segundo te mandei, no tempo do mês de Abibe; porque no mês de Abibe saíste do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 19, 'Todo o que abre madre, meu é; e de teu gado todo primeiro de vaca ou de ovelha que for macho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 20, 'Porém resgatarás com cordeiro o primeiro do asno; e se não o resgatares, lhe cortarás a cabeça. Resgatarás todo primogênito de teus filhos, e não serão vistos vazios diante de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 21, 'Seis dias trabalharás, mas no sétimo dia cessarás: cessarás ainda na arada e na colheita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 22, 'E te farás a festa das semanas aos princípios da colheita do trigo: e a festa da colheita à volta do ano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 23, 'Três vezes no ano será visto todo homem teu diante do Soberano SENHOR, Deus de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 24, 'Porque eu lançarei as nações de tua presença, e alargarei teu termo: e ninguém cobiçará tua terra, quando tu subires para ser visto diante do SENHOR teu Deus três vezes no ano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 25, 'Não oferecerás com levedado o sangue de meu sacrifício; nem ficará da noite para a manhã o sacrifício da festa da páscoa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 26, 'A primícia dos primeiros frutos de tua terra meterás na casa do SENHOR teu Deus. Não cozerás o cabrito no leite de sua mãe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 27, 'E o SENHOR disse a Moisés: Escreve tu estas palavras; porque conforme estas palavras fiz a aliança contigo e com Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 28, 'E ele esteve ali com o SENHOR quarenta dias e quarenta noites: não comeu pão, nem bebeu água; e escreveu em tábuas as palavras da aliança, os dez dizeres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 29, 'E aconteceu que, descendo Moisés do monte Sinai com as duas tábuas do testemunho em sua mão, enquanto descia do monte, não sabia ele que a pele de seu rosto resplandecia, depois que havia com ele falado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 30, 'E olhou Arão e todos os filhos de Israel a Moisés, e eis que a pele de seu rosto era resplandescente; e tiveram medo de chegar-se a ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 31, 'E chamou-os Moisés; e Arão e todos os príncipes da congregação voltaram-se a ele, e Moisés lhes falou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 32, 'E depois se chegaram todos os filhos de Israel, aos quais mandou todas as coisas que o SENHOR lhe havia dito no monte de Sinai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 33, 'E quando acabou Moisés de falar com eles, pôs um véu sobre seu rosto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 34, 'E quando vinha Moisés diante do SENHOR para falar com ele, tirava-se o véu até que saía; e saindo, falava com os filhos de Israel o que lhe era mandado;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 34, 35, 'E viam os filhos de Israel o rosto de Moisés, que a pele de seu rosto era resplandescente; e voltava Moisés a pôr o véu sobre seu rosto, até que entrava a falar com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 1, 'E Moisés fez juntar toda a congregação dos filhos de Israel, e disse-lhes: Estas são as coisas que o SENHOR mandou que façais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 2, 'Seis dias se fará obra, mas o dia sétimo vos será santo, sábado de repouso ao SENHOR: qualquer um que nele fizer obra morrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 3, 'Não acendereis fogo em todas as vossas moradas no dia do sábado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 4, 'E falou Moisés a toda a congregação dos filhos de Israel, dizendo: Isto é o que o SENHOR mandou, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 5, 'Tomai dentre vós oferta para o SENHOR: todo generoso de coração a trará ao SENHOR: ouro, prata, bronze;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 6, 'E azul, e púrpura, e carmesim, e linho fino, e pelo de cabras;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 7, 'E couros vermelhos de carneiros, e couros finos, e madeira de acácia;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 8, 'E azeite para a luminária, e especiarias aromáticas para o azeite da unção, e para o incenso aromático;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 9, 'E pedras de ônix, e demais pedrarias, para o éfode, e para o peitoral.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 10, 'E todo sábio de coração dentre vós, virá e fará todas as coisas que o SENHOR mandou:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 11, 'O tabernáculo, sua tenda, e sua coberta, e seus anéis, e suas tábuas, suas barras, suas colunas, e suas bases;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 12, 'A arca, e suas varas, o propiciatório, e o véu da tenda;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 13, 'A mesa, e suas varas, e todos os seus utensílios, e o pão da proposição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 14, 'O candelabro da luminária, e seus utensílios, e suas lâmpadas, e o azeite para a luminária;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 15, 'E o altar do incenso, e suas varas, e o azeite da unção, e o incenso aromático, e a cortina da porta, para a entrada do tabernáculo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 16, 'O altar do holocausto, e sua grelha de bronze, e suas varas, e todos os seus utensílios, e a pia com sua base;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 17, 'As cortinas do átrio, suas colunas, e suas bases, e a cortina da porta do átrio;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 18, 'As estacas do tabernáculo, e as estacas do átrio, e suas cordas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 19, 'As vestimentas dos serviço para ministrar no santuário, as sagradas vestimentas de Arão o sacerdote, e as vestimentas de seus filhos para servir no sacerdócio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 20, 'E saiu toda a congregação dos filhos de Israel de diante de Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 21, 'E veio todo homem a quem seu coração estimulou, e todo aquele a quem seu espírito lhe deu vontade, e trouxeram oferta ao SENHOR para a obra do tabernáculo do testemunho, e para toda sua confecção, e para as sagradas vestimentas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 22, 'E vieram tanto homens como mulheres, todo voluntário de coração, e trouxeram correntes e pendentes, anéis e braceletes, e toda joia de ouro; e qualquer um oferecia oferta de ouro ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 23, 'Todo homem que se achava com material azul, ou púrpura, ou carmesim, ou linho fino, ou pelo de cabras, ou odres vermelhos de carneiros, ou couros finos, o trazia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 24, 'Qualquer um que oferecia oferta de prata ou de bronze, trazia ao SENHOR a oferta: e todo o que se achava com madeira de acácia, trazia-a para toda a obra do serviço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 25, 'Além disso todas as mulheres sábias de coração fiavam de suas mãos, e traziam o que haviam fiado: azul, ou púrpura, ou carmesim, ou linho fino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 26, 'E todas as mulheres cujo coração as levantou em sabedoria, fiaram pelos de cabras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 27, 'E os príncipes trouxeram pedras de ônix, e as pedras dos engastes para o éfode e o peitoral;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 28, 'E a especiaria aromática e azeite, para a luminária, e para o azeite da unção, e para o incenso aromático.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 29, 'Dos filhos de Israel, tanto homens como mulheres, todos os que tiveram coração voluntário para trazer para toda a obra, que o SENHOR havia mandado por meio de Moisés que fizessem, trouxeram oferta voluntária ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 30, 'E disse Moisés aos filhos de Israel: Olhai, o SENHOR nomeou a Bezalel filho de Uri, filho de Hur, da tribo de Judá;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 31, 'E o encheu de espírito de Deus, em sabedoria, em inteligência, e em conhecimento, e em todo artifício,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 32, 'Para projetar inventos, para trabalhar em ouro, e em prata, e em bronze,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 33, 'E em obra de pedrarias para engastar, e em obra de madeira, para trabalhar em toda invenção engenhosa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 34, 'E pôs em seu coração o que podia ensinar, tanto ele como Aoliabe filho de Aisamaque, da tribo de Dã:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 35, 35, 'E os encheu de sabedoria de coração, para que façam toda obra de artifício, e de invenção, e de recamado em azul, e em púrpura, e em carmesim, e em linho fino, e em tear; para que façam todo trabalho, e inventem todo desenho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 1, 'Fez, pois, Bezalel e Aoliabe, e todo homem sábio de coração, a quem o SENHOR deu sabedoria e inteligência para que soubessem fazer toda a obra do serviço do santuário, todas as coisas que havia mandado o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 2, 'E Moisés chamou a Bezalel e a Aoliabe, e a todo homem sábio de coração, em cujo coração havia dado o SENHOR sabedoria, e a todo homem a quem seu coração lhe moveu a chegar-se à obra, para trabalhar nela;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 3, 'E tomaram de diante de Moisés toda a oferta que os filhos de Israel haviam trazido para a obra do serviço do santuário, a fim de fazê-la. E eles lhe traziam ainda oferta voluntária cada manhã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 4, 'Vieram, portanto, todos os mestres que faziam toda a obra do santuário, cada um da obra que fazia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 5, 'E falaram a Moisés, dizendo: O povo traz muito mais do que é necessário para o trabalho de fazer a obra que o SENHOR mandou que se faça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 6, 'Então Moisés mandou apregoar pelo acampamento, dizendo: Nenhum homem nem mulher faça mais obra para oferecer para o santuário. E assim foi o povo impedido de oferecer;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 7, 'Pois tinha material abundante para fazer toda a obra, e sobrava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 8, 'E todos os sábios de coração entre os que faziam a obra, fizeram o tabernáculo de dez cortinas, de linho torcido, e de material azul, e de púrpura e carmesim; as quais fizeram de obra prima, com querubins.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 9, 'O comprimento da uma cortina era de vinte e oito côvados, e a largura de quatro côvados: todas as cortinas tinham uma mesma medida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 10, 'E juntou as cinco cortinas a uma com a outra: também uniu as outras cinco cortinas uma com aa outra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 11, 'E fez as laçadas de cor de material azul na orla de uma cortina, na margem, à juntura; e assim fez na orla à extremidade da segunda cortina, na juntura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 12, 'Cinquenta laçadas fez em um cortina, e outras cinquenta na segunda cortina, na margem, na juntura; umas laçadas em frente das outras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 13, 'Fez também cinquenta colchetes de ouro, com os quais juntou as cortinas, uma com a outra; e fez-se um tabernáculo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 14, 'Fez também cortinas de pelo de cabras para a tenda sobre o tabernáculo, e as fez em número de onze.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 15, 'O comprimento de uma cortina era de trinta côvados, e a largura de quatro côvados: as onze cortinas tinham uma mesma medida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 16, 'E juntou as cinco cortinas à parte, e as seis cortinas à parte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 17, 'Fez também cinquenta laçadas na orla da última cortina na juntura, e outras cinquenta laçadas na orla da outra cortina na juntura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 18, 'Fez também cinquenta colchetes de bronze para juntar a tenda, de modo que fosse uma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 19, 'E fez uma coberta para a tenda de couros vermelhos de carneiros, e uma coberta encima de couros finos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 20, 'Também fez as tábuas para o tabernáculo de madeira de acácia, para estarem na vertical.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 21, 'O comprimento de cada tábua de dez côvados, e de côvado e meio a largura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 22, 'Cada tábua tinha dois encaixes fixos um diante do outro: assim fez todas as tábuas do tabernáculo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 23, 'Fez, pois, as tábuas para o tabernáculo: vinte tábuas ao lado do sul.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 24, 'Fez também as quarenta bases de prata debaixo das vinte tábuas: duas bases debaixo de uma tábua para seus dois encaixes, e duas bases debaixo da outra tábua para seus dois encaixes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 25, 'E para o outro lado do tabernáculo, à parte do norte, fez vinte tábuas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 26, 'Com suas quarenta bases de prata: duas bases debaixo de uma tábua, e duas bases debaixo da outra tábua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 27, 'E para o lado ocidental do tabernáculo fez seis tábuas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 28, 'Para as esquinas do tabernáculo nos dois lados fez duas tábuas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 29, 'As quais se juntavam por baixo, e também por cima a uma argola: e assim fez à uma e à outra nos dois cantos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 30, 'Eram, pois, oito tábuas, e suas bases de prata dezesseis; duas bases debaixo de cada tábua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 31, 'Fez também as barras de madeira de acácia; cinco para as tábuas do um lado do tabernáculo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 32, 'E cinco barras para as tábuas do outro lado do tabernáculo, e cinco barras para as tábuas do lado do tabernáculo à parte ocidental.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 33, 'E fez que a barra do meio passasse por meio das tábuas do um extremo ao outro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 34, 'E cobriu as tábuas de ouro, e fez de ouro os anéis delas por de onde passassem as barras: cobriu também de ouro as barras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 35, 'Fez assim o véu de azul, e púrpura, e carmesim, e linho torcido, o qual fez com querubins de delicada obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 36, 'E para ele fez quatro colunas de madeira de acácia; e cobriu-as de ouro, os capitéis das quais eram de ouro; e fez para elas quatro bases de prata de fundição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 37, 'Fez também o véu para a porta do tabernáculo, de azul, e púrpura, e carmesim, e linho torcido, obra de bordador;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 36, 38, 'E suas cinco colunas com seus capitéis: e cobriu as cabeças delas e suas molduras de ouro: mas suas cinco bases as fez de bronze.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 37, 1, 'Fez também Bezalel a arca de madeira de acácia: seu comprimento era de dois côvados e meio, e de côvado e meio sua largura, e sua altura de outro côvado e meio:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 37, 2, 'E cobriu-a de ouro puro por de dentro e por de fora, e fez-lhe uma borda de ouro em derredor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 37, 3, 'Fez-lhe também de fundição quatro anéis de ouro a seus quatro cantos; em um lado dois anéis e no outro lado dois anéis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 37, 4, 'Fez também as varas de madeira de acácia, e cobriu-as de ouro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 37, 5, 'E meteu as varas pelos anéis aos lados da arca, para levar a arca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 37, 6, 'Fez também a coberta de ouro puro: seu comprimento de dois côvados e meio, e sua largura de côvado e meio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 37, 7, 'Fez também os dois querubins de ouro, os fez lavrados a martelo, aos duas extremidades do propiciatório:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 37, 8, 'Um querubim desta parte ao um extremo, e o outro querubim da outra parte ao outro extremo do propiciatório: fez os querubins a suas duas extremidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 37, 9, 'E os querubins estendiam suas asas por cima, cobrindo com suas asas o propiciatório: e seus rostos um em frente do outro, até o propiciatório os rostos dos querubins.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 37, 10, 'Fez também a mesa de madeira de acácia; seu comprimento de dois côvados, e sua largura de um côvado, e de côvado e meio sua altura;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 37, 11, 'E cobriu-a de ouro puro, e fez-lhe uma borda de ouro em derredor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 37, 12, 'Fez-lhe também uma moldura ao redor, da largura de uma mão, à qual moldura fez a borda de ouro ao redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 37, 13, 'Fez-lhe também de fundição quatro anéis de ouro, e os pôs aos quatro cantos que correspondiam aos quatro pés dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 37, 14, 'Diante da moldura estavam os anéis, pelos quais se metessem as varas para levar a mesa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 37, 15, 'E fez as varas de madeira de acácia para levar a mesa, e cobriu-as de ouro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 37, 16, 'Também fez os utensílios que haviam de estar sobre a mesa, seus pratos, e suas colheres, e suas tigelas e suas bacias com que se havia de fazer libações, de ouro fino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 37, 17, 'Fez também o candelabro de ouro puro, e o fez lavrado a martelo: seu pé e sua haste, seus copos, seus botões e suas flores eram do mesmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 37, 18, 'De seus lados saíam seis braços; três braços de um lado do candelabro, e outros três braços do outro lado do candelabro:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 37, 19, 'Em um braço, três copos forma de amêndoas, um botão e uma flor; e no outro braço três copos forma de amêndoas, um botão e uma flor: e assim nos seis braços que saíam do candelabro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 37, 20, 'E no candelabro havia quatro copos forma de amêndoas, seus botões e suas flores:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 37, 21, 'E um botão debaixo dos dois braços do mesmo, e outro botão debaixo dos outros dois braços do mesmo, e outro botão debaixo dos outros dois braços do mesmo, conforme os seis braços que saíam dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 37, 22, 'Seus botões e seus braços eram do mesmo; tudo era uma peça lavrada a martelo, de ouro puro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 37, 23, 'Fez também suas sete lâmpadas, e seus tenazes, e seus apagadores, de ouro puro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 37, 24, 'De um talento de ouro puro o fez, com todos os seus utensílios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 37, 25, 'Fez também o altar do incenso de madeira de acácia: um côvado seu comprimento, e outro côvado sua largura, era quadrado; e sua altura de dois côvados; e suas pontas da mesma peça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 37, 26, 'E cobriu-o de ouro puro, sua mesa e suas paredes ao redor, e suas pontas: e fez-lhe uma coroa de ouro ao redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 37, 27, 'Fez-lhe também dois anéis de ouro debaixo da coroa nos dois cantos aos dois lados, para passar por eles as varas com que havia de ser conduzido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 37, 28, 'E fez as varas de madeira de acácia, e cobriu-as de ouro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 37, 29, 'Fez também o azeite santo da unção, e o fino incenso aromático, de obra de perfumista.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 38, 1, 'Igualmente fez o altar do holocausto de madeira de acácia: seu comprimento de cinco côvados, e sua largura de outros cinco côvados, quadrado, e de três côvados de altura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 38, 2, 'E fez-lhe suas pontas a seus quatro cantos, os quais eram da mesma peça, e cobriu-o de bronze.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 38, 3, 'Fez também todos os utensílios do altar: caldeirões, e tenazes, e bacias, e garfos, e pás: todos os seus utensílios fez de bronze.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 38, 4, 'E fez para o altar a grelha de bronze, de feitura de rede, que pôs em sua borda por debaixo até o meio do altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 38, 5, 'Fez também quatro anéis de fundição aos quatro extremos da grelha de bronze, para meter as varas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 38, 6, 'E fez as varas de madeira de acácia, e cobriu-as de bronze.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 38, 7, 'E meteu as varas pelos anéis aos lados do altar, para levá-lo com elas: oco o fez, de tábuas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 38, 8, 'Também fez a pia de bronze, com sua base de bronze, dos espelhos das que vigiavam à porta do tabernáculo do testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 38, 9, 'Fez também o átrio; à parte sul as cortinas do átrio eram de cem côvados, de linho torcido:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 38, 10, 'Suas colunas vinte, com suas vinte bases de bronze: os capitéis das colunas e suas molduras, de prata.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 38, 11, 'E à parte do norte cortinas de cem côvados: suas colunas vinte, com suas vinte bases de bronze; os capitéis das colunas e suas molduras, de prata.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 38, 12, 'À parte do ocidente cortinas de cinquenta côvados: suas colunas dez, e suas dez bases; os capitéis das colunas e suas molduras, de prata.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 38, 13, 'E à parte oriental, ao levante, cortinas de cinquenta côvados:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 38, 14, 'Ao um lado cortinas de quinze côvados, suas três colunas, e suas três bases;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 38, 15, 'Ao outro lado, de uma parte e da outra da porta do átrio, cortinas de a quinze côvados, suas três colunas, e suas três bases.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 38, 16, 'Todas as cortinas do átrio ao redor eram de linho torcido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 38, 17, 'E as bases das colunas eram de bronze; os capitéis das colunas e suas molduras, de prata; também as cobertas das cabeças delas, de prata: e todas as colunas do átrio tinham molduras de prata.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 38, 18, 'E a cortina da porta do átrio foi de obra de bordado, de azul, e púrpura, e carmesim, e linho torcido: o comprimento de vinte côvados, e a altura na largura de cinco côvados, conforme as cortinas do átrio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 38, 19, 'E suas colunas foram quatro com suas quatro bases de bronze: e seus capitéis de prata; e as cobertas dos capitéis delas e suas molduras, de prata.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 38, 20, 'E todas as estacas do tabernáculo e do átrio ao redor foram de bronze.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 38, 21, 'Estas são as contas do tabernáculo, do tabernáculo do testemunho, o que foi contado de ordem de Moisés por meio de Itamar, filho de Arão sacerdote, para o ministério dos levitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 38, 22, 'E Bezalel, filho de Uri, filho de Hur, da tribo de Judá, fez todas as coisas que o SENHOR mandou a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 38, 23, 'E com ele estava Aoliabe, filho de Aisamaque, da tribo de Dã, artífice, e desenhador, e bordador em material azul, e púrpura, e carmesim, e linho fino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 38, 24, 'Todo o ouro gasto na obra, em toda a obra do santuário, o qual foi ouro de oferta, foi vinte e nove talentos, e setecentos e trinta siclos, segundo o siclo do santuário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 38, 25, 'E a prata dos contados da congregação foi cem talentos, e mil setecentos setenta e cinco siclos, segundo o siclo do santuário:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 38, 26, 'Meio por cabeça, meio siclo, segundo o siclo do santuário, a todos os que passaram por contagem de idade de vinte anos e acima, que foram seiscentos três mil quinhentos cinquenta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 38, 27, 'Houve também cem talentos de prata para fazer de fundição as bases do santuário e as bases do véu: em cem bases cem talentos, a talento por base.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 38, 28, 'E dos mil setecentos setenta e cinco siclos fez os capitéis das colunas, e cobriu os capitéis delas, e as cingiu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 38, 29, 'E o bronze da oferta foi setenta talentos, e dois mil quatrocentos siclos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 38, 30, 'Do qual fez as bases da porta do tabernáculo do testemunho, e o altar de bronze, e sua grelha de bronze, e todos os utensílios do altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 38, 31, 'E as bases do átrio ao redor, e as bases da porta do átrio, e todas as estacas do tabernáculo, e todas as estacas do átrio ao redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 1, 'E do material azul, e púrpura, e carmesim, fizeram as vestimentas do ministério para ministrar no santuário, e também fizeram as vestiduras sagradas para Arão; como o SENHOR o havia mandado a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 2, 'Fez também o éfode de ouro, de azul e púrpura e carmesim, e linho torcido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 3, 'E estenderam as placas de ouro, e cortaram cachos para tecê-los entre o azul, e entre a púrpura, e entre o carmesim, e entre o linho, com delicada obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 4, 'Fizeram-lhe as ombreiras que se juntassem; e uniam-se em seus dois lados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 5, 'E o cinto do éfode que estava sobre ele, era do mesmo, conforme sua obra; de ouro, material azul, e púrpura, e carmesim, e linho torcido; como o SENHOR o havia mandado a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 6, 'E lavraram as pedras de ônix cercadas de engastes de ouro, gravada de gravura de selo com os nomes dos filhos de Israel:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 7, 'E as pôs sobre as ombreiras do éfode, por pedras de memória aos filhos de Israel; como o SENHOR o havia a Moisés mandado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 8, 'Fez também o peitoral de primorosa obra, como a obra do éfode, de ouro, azul, e púrpura, e carmesim, e linho torcido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 9, 'Era quadrado; dobrado fizeram o peitoral: sua comprimento era de um palmo, e de um palmo sua largura, dobrado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 10, 'E engastaram nele quatro ordens de pedras. A primeira ordem era um sárdio, um topázio, e um carbúnculo: este a primeira ordem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 11, 'A segunda ordem, uma esmeralda, uma safira, e um diamante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 12, 'A terceira ordem, um jacinto, uma ágata, e uma ametista.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 13, 'E a quarta ordem, um berilo, um ônix, e um jaspe: cercadas e encaixadas em seus engastes de ouro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 14, 'As quais pedras eram conforme os nomes dos filhos de Israel, doze segundo os nomes deles; como gravuras de selo, cada uma com seu nome segundo as doze tribos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 15, 'Fizeram também sobre o peitoral as correntes pequenas de feitura de trança, de ouro puro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 16, 'Fizeram também os dois engastes e os dois anéis, de ouro; os quais dois anéis de ouro puseram nas duas extremidades do peitoral.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 17, 'E puseram as duas tranças de ouro naqueles dois anéis aos extremos do peitoral.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 18, 'E fixaram as duas extremidades das duas tranças nos dois engastes, que puseram sobre as ombreiras do éfode, na parte dianteira dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 19, 'E fizeram dois anéis de ouro, que puseram nas duas extremidades do peitoral, em sua orla, à parte baixa do éfode.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 20, 'Fizeram também dois anéis de ouro, os quais puseram nas duas ombreiras do éfode, abaixo na parte dianteira, diante de sua juntura, sobre o cinto do éfode.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 21, 'E ataram o peitoral de seus anéis aos anéis do éfode com um cordão de material azul, para que estivesse sobre o cinto do mesmo éfode, e não se separasse o peitoral do éfode; como o SENHOR o havia mandado a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 22, 'Fez também o manto do éfode de obra de tecelão, todo de azul.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 23, 'Com sua abertura em meio dele, como a abertura de um colarinho, com uma borda em derredor da abertura, para que não se rompesse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 24, 'E fizeram nas orlas do manto as romãs de azul, e púrpura, e carmesim, e linho torcido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 25, 'Fizeram também os sinos de ouro puro, os quais sinos puseram entre as romãs pelas orlas do manto ao redor entre as romãs:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 26, 'Um sino e uma romã, um sino e uma romã ao redor, nas orlas do manto, para ministrar; como o SENHOR o mandou a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 27, 'Igualmente fizeram as túnicas de linho fino de obra de tecelão, para Arão e para seus filhos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 28, 'Também a mitra de linho fino, e os adornos das tiaras de linho fino, e os calções de linho, de linho torcido;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 29, 'Também o cinto de linho torcido, e de material azul, e púrpura, e carmesim, de obra de bordador; como o SENHOR o mandou a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 30, 'Fizeram também a prancha da coroa santa de ouro puro, e escreveram nela de gravura de selo, o rótulo, SANTIDADE AO SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 31, 'E puseram nela um cordão de azul, para colocá-la em alto sobre a mitra; como o SENHOR o havia mandado a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 32, 'E foi acabada toda a obra do tabernáculo, do tabernáculo do testemunho: e fizeram os filhos de Israel como o SENHOR o havia mandado a Moisés: assim o fizeram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 33, 'E trouxeram o tabernáculo a Moisés, o tabernáculo e todos os seus utensílios; seus colchetes, suas tábuas, suas barras, e suas colunas, e suas bases;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 34, 'E a coberta de peles vermelhas de carneiros, e a coberta de peles finas, e o véu da cortina;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 35, 'A arca do testemunho, e suas varas, e o propiciatório;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 36, 'A mesa, todos os seus utensílios, e o pão da proposição;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 37, 'O candelabro limpo, suas lâmpadas, as lâmpadas que deviam manter-se em ordem, e todos os seus utensílios, e o azeite para a luminária;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 38, 'E o altar de ouro, e o azeite da unção, e o incenso aromático, e a cortina para a porta do tabernáculo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 39, 'O altar de bronze, com sua grelha de bronze, suas varas, e todos os seus utensílios; e a pia, e sua base;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 40, 'As cortinas do átrio, e suas colunas, e suas bases, e a cortina para a porta do átrio, e suas cordas, e suas estacas, e todos os vasos do serviço do tabernáculo, do tabernáculo do testemunho;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 41, 'As vestimentas do serviço para ministrar no santuário, as sagradas vestiduras para Arão o sacerdote, e as vestiduras de seus filhos, para ministrar no sacerdócio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 42, 'Em conformidade a todas as coisas que o SENHOR havia mandado a Moisés, assim fizeram os filhos de Israel toda a obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 39, 43, 'E viu Moisés toda a obra, e eis que a fizeram como o SENHOR havia mandado; e abençoou-os.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 1, 'E o SENHOR falou a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 2, 'No primeiro dia do mês primeiro farás levantar o tabernáculo, o tabernáculo do testemunho:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 3, 'E porás nele a arca do testemunho, e a cobrirás com o véu:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 4, 'E meterás a mesa, e a porás em ordem: meterás também o candelabro e acenderás suas lâmpadas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 5, 'E porás o altar de ouro para o incenso diante da arca do testemunho, e porás a cortina diante da porta do tabernáculo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 6, 'Depois porás o altar do holocausto diante da porta do tabernáculo, do tabernáculo do testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 7, 'Logo porás a pia entre o tabernáculo do testemunho e o altar; e porás água nela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 8, 'Finalmente porás o átrio em derredor, e a cortina da porta do átrio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 9, 'E tomarás o azeite da unção e ungirás o tabernáculo, e tudo o que está nele; e lhe santificarás com todos os seus utensílios, e será santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 10, 'Ungirás também o altar do holocausto e todos os seus utensílios: e santificarás o altar, e será um altar santíssimo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 11, 'Também ungirás a pia e sua base, e a santificarás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 12, 'E farás chegar a Arão e a seus filhos à porta do tabernáculo do testemunho, e os lavarás com água.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 13, 'E farás vestir a Arão as vestimentas sagradas, e o ungirás, e o consagrarás, para que seja meu sacerdote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 14, 'Depois farás chegar seus filhos, e lhes vestirás as túnicas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 15, 'E os ungirás como ungiste a seu pai, e serão meus sacerdotes: e será que sua unção lhes servirá por sacerdócio perpétuo por suas gerações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 16, 'E Moisés fez conforme tudo o que o SENHOR lhe mandou; assim o fez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 17, 'E assim no dia primeiro do primeiro mês, no segundo ano, o tabernáculo foi erigido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 18, 'E Moisés fez levantar o tabernáculo, e assentou suas bases, e colocou suas tábuas, e pôs suas barras, e fez erguer suas colunas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 19, 'E estendeu a tenda sobre o tabernáculo, e pôs a cobertura encima do mesmo; como o SENHOR havia mandado a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 20, 'E tomou e pôs o testemunho dentro da arca, e colocou as varas na arca, e encima o propiciatório sobre a arca:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 21, 'E meteu a arca no tabernáculo, e pôs o véu da tenda, e cobriu a arca do testemunho; como o SENHOR havia mandado a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 22, 'E pôs a mesa no tabernáculo do testemunho, ao lado norte da cortina, fora do véu:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 23, 'E sobre ela pôs por ordem os pães diante do SENHOR, como o SENHOR havia mandado a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 24, 'E pôs o candelabro no tabernáculo do testemunho, em frente da mesa, ao lado sul da cortina.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 25, 'E acendeu as lâmpadas diante do SENHOR; como o SENHOR havia mandado a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 26, 'Pôs também o altar de ouro no tabernáculo do testemunho, diante do véu:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 27, 'E acendeu sobre ele o incenso aromático; como o SENHOR havia mandado a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 28, 'Pôs também a cortina da porta do tabernáculo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 29, 'E colocou o altar do holocausto à porta do tabernáculo, do tabernáculo do testemunho; e ofereceu sobre ele holocausto e oferta de cereais; como o SENHOR havia mandado a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 30, 'E pôs a pia entre o tabernáculo do testemunho e o altar; e pôs nela água para lavar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 31, 'E Moisés e Arão e seus filhos lavavam nela suas mãos e seus pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 32, 'Quando entravam no tabernáculo do testemunho, e quando se traziam ao altar, se lavavam; como o SENHOR havia mandado a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 33, 'Finalmente erigiu o átrio em derredor do tabernáculo e do altar, e pôs a cortina da porta do átrio. E assim acabou Moisés a obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 34, 'Então uma nuvem cobriu o tabernáculo do testemunho, e a glória do SENHOR encheu o tabernáculo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 35, 'E não podia Moisés entrar no tabernáculo do testemunho, porque a nuvem estava sobre ele, e a glória do SENHOR o tinha enchido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 36, 'E quando a nuvem se erguia do tabernáculo, os filhos de Israel se moviam em todas suas jornadas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 37, 'Porém se a nuvem não se erguia, não se partiam até o dia em que ela se erguia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 2, 'Êxodo', 'Êx', 40, 38, 'Porque a nuvem do SENHOR estava de dia sobre o tabernáculo, e o fogo estava de noite nele, à vista de toda a casa de Israel, em todas as suas jornadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 1, 1, 'E chamou o SENHOR a Moisés, e falou com ele desde o tabernáculo do testemunho, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 1, 2, 'Fala aos filhos de Israel, e dize-lhes: Quando algum dentre vós oferecer oferta ao SENHOR, de gado vacum ou ovelha fareis vossa oferta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 1, 3, 'Se sua oferta for holocausto de vacas, macho sem mácula o oferecerá: de sua vontade o oferecerá à porta do tabernáculo do testemunho diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 1, 4, 'E porá sua mão sobre a cabeça do holocausto; e ele o aceitará para expiar-lhe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 1, 5, 'Então degolará o bezerro na presença do SENHOR; e os sacerdotes, filhos de Arão, oferecerão o sangue, e o espargirão ao redor sobre o altar, o qual está à porta do tabernáculo do testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 1, 6, 'E tirará a pele do holocausto, e o dividirá em suas peças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 1, 7, 'E os filhos de Arão sacerdote porão fogo sobre o altar, e porão a lenha sobre o fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 1, 8, 'Logo os sacerdotes, filhos de Arão, acomodarão as peças, a cabeça e o redenho, sobre a lenha que está sobre o fogo, que haverá encima do altar:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 1, 9, 'E lavará com água seus intestinos e suas pernas: e o sacerdote fará arder tudo sobre o altar: holocausto é, oferta acesa de cheiro suave ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 1, 10, 'E se sua oferta para holocausto for de ovelhas, dos cordeiros, ou das cabras, macho sem defeito o oferecerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 1, 11, 'E há de degolá-lo ao lado norte do altar diante do SENHOR: e os sacerdotes, filhos de Arão, espargirão seu sangue sobre o altar ao redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 1, 12, 'E o dividirá em suas peças, com sua cabeça e seu redenho; e o sacerdote as acomodará sobre a lenha que está sobre o fogo, que haverá encima do altar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 1, 13, 'E lavará suas entranhas e suas pernas com água; e o sacerdote o oferecerá tudo, e o fará arder sobre o altar; holocausto é, oferta acesa de cheiro suave ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 1, 14, 'E se o holocausto se houver de oferecer ao SENHOR de aves, apresentará sua oferta de rolinhas, ou de pombinhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 1, 15, 'E o sacerdote a oferecerá sobre o altar, e há de tirar-lhe a cabeça, e fará que arda no altar; e seu sangue será espremido sobre a parede do altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 1, 16, 'E lhe há de tirar o papo e as penas, o qual lançará junto ao altar, até o oriente, no lugar das cinzas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 1, 17, 'E a fenderá por suas asas, mas não a dividirá em dois: e o sacerdote a fará arder sobre o altar, sobre a lenha que estará no fogo; holocausto é, oferta acesa de cheiro suave ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 2, 1, 'E quando alguma pessoa oferecer uma oferta de alimentos ao SENHOR, sua oferta será boa farinha, sobre a qual lançará azeite, e porá sobre ela incenso;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 2, 2, 'e a trará aos sacerdotes, filhos de Arão; e disso tomará o sacerdote seu punho cheio de sua boa farinha e de seu azeite, com todo seu incenso, e o fará arder sobre o altar: oferta acesa para memorial, de aroma suave ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 2, 3, 'E a sobra da oferta será de Arão e de seus filhos: é coisa santíssima das ofertas que se queimam ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 2, 4, 'E quando ofereceres oferta de alimentos, cozida no forno, será de tortas de boa farinha sem levedura, amassadas com azeite, e massas sem levedura untadas com azeite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 2, 5, 'Mas se a tua oferta for oferta de alimentos [preparados] em panelas, será de boa farinha sem levedura, amassada com azeite,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 2, 6, 'a qual partirás em peças, e espalharás azeite sobre ela; é oferta de alimentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 2, 7, 'E se a tua oferta de alimentos for oferta [preparada] em frigideira, ela será feita de boa farinha com azeite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 2, 8, 'E trarás ao SENHOR a oferta que se fará destas coisas, e a apresentarás ao sacerdote, o qual a chegará ao altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 2, 9, 'E tomará o sacerdote daquela oferta de alimentos em sua memória, e a fará arder sobre o altar; oferta acesa, de suave aroma ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 2, 10, 'E o restante da oferta será de Arão e de seus filhos; é coisa santíssima das ofertas que se queimam ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 2, 11, 'Nenhuma oferta que oferecerdes ao SENHOR será com levedura; porque de nenhuma coisa levedada, nem de nenhum mel, se deverá queimar oferta ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 2, 12, 'Na oferta das primícias as oferecereis ao SENHOR: mas não subirão sobre o altar em cheiro suave.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 2, 13, 'E temperarás toda oferta de teu presente com sal; e não farás que falte jamais da tua oferta de alimentos o sal da aliança de teu Deus; em toda oferta tua oferecerás sal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 2, 14, 'E se ofereceres ao SENHOR oferta de alimentos das primícias, tostarás ao fogo as espigas verdes, e o grão esmigalhado oferecerás por oferta das tuas primícias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 2, 15, 'E porás sobre ela azeite, e porás sobre ela incenso: é oferta de alimentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 2, 16, 'E o sacerdote fará arder, em memória da oferta de alimentos, parte de seu grão esmigalhado, e de seu azeite com todo o seu incenso; é oferta acesa ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 3, 1, 'E se sua oferta for sacrifício pacífico, se houver de oferecê-lo de gado vacum, seja macho ou fêmea, sem defeito o oferecerá diante do SENHOR:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 3, 2, 'E porá sua mão sobre a cabeça de sua oferta, e a degolará à porta do tabernáculo do testemunho; e os sacerdotes, filhos de Arão, espargirão seu sangue sobre o altar em derredor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 3, 3, 'Logo oferecerá do sacrifício pacífico, por oferta acesa ao SENHOR, a gordura que cobre os intestinos, e toda a gordura que está sobre as entranhas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 3, 4, 'E os dois rins, e a gordura que está sobre eles, e sobre os lombos, e com os rins tirará o redenho que está sobre o fígado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 3, 5, 'E os filhos de Arão farão arder isto no altar, sobre o holocausto que estará sobre a lenha que haverá encima do fogo; é oferta de cheiro suave ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 3, 6, 'Mas se de ovelhas for sua oferta para sacrifício pacífico ao SENHOR, seja macho ou fêmea, oferecê-la-á sem mácula.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 3, 7, 'Se oferecer cordeiro por sua oferta, há de oferecê-lo diante do SENHOR:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 3, 8, 'E porá sua mão sobre a cabeça de sua oferta, e depois a degolará diante do tabernáculo do testemunho; e os filhos de Arão espargirão seu sangue sobre o altar em derredor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 3, 9, 'E do sacrifício pacífico oferecerá por oferta acesa ao SENHOR, sua gordura, e a cauda inteira, a qual tirará a raiz do espinhaço, e a gordura que cobre os intestinos, e toda a gordura que está sobre as entranhas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 3, 10, 'Também os dois rins, e a gordura que está sobre eles, e o que está sobre os lombos, e com os rins tirará o redenho de sobre o fígado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 3, 11, 'E o sacerdote fará arder isto sobre o altar; comida de oferta acesa ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 3, 12, 'E se for cabra sua oferta oferecê-la-á diante do SENHOR:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 3, 13, 'E porá sua mão sobre a cabeça dela, e a degolará diante do tabernáculo do testemunho; e os filhos de Arão espargirão seu sangue sobre o altar em derredor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 3, 14, 'Depois oferecerá dela sua oferta acesa ao SENHOR; a gordura que cobre os intestinos, e toda a gordura que está sobre as entranhas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 3, 15, 'E os dois rins, e a gordura que está sobre eles, e o que está sobre os lombos, e com os rins tirará o redenho de sobre o fígado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 3, 16, 'E o sacerdote fará arder isto sobre o altar; é comida de oferta que se queima em cheiro suave ao SENHOR: a gordura tudo é do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 3, 17, 'Estatuto perpétuo por vossas gerações; em todas as vossas moradas, nenhuma gordura nem nenhum sangue comereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 1, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 2, 'Fala aos filhos de Israel, dizendo: Quando alguma pessoa pecar por acidente em algum dos mandamentos do SENHOR sobre coisas que não se devem fazer, e agir contra algum deles;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 3, 'Se sacerdote ungido pecar segundo o pecado do povo, oferecerá ao SENHOR, por seu pecado que houver cometido, um bezerro sem mácula para expiação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 4, 'E trará o bezerro à porta do tabernáculo do testemunho diante do SENHOR, e porá sua mão sobre a cabeça do bezerro, e o degolará diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 5, 'E o sacerdote ungido tomará do sangue do bezerro, e a trará ao tabernáculo do testemunho;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 6, 'E molhará o sacerdote seu dedo no sangue, e espargirá daquele sangue sete vezes diante do SENHOR, até o véu do santuário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 7, 'E porá o sacerdote do sangue sobre as pontas do altar do incenso aromático, que está no tabernáculo do testemunho diante do SENHOR: e lançará todo o sangue do bezerro ao pé do altar do holocausto, que está à porta do tabernáculo do testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 8, 'E tomará do bezerro para a expiação toda a sua gordura, a gordura que cobre os intestinos, e toda a gordura que está sobre as entranhas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 9, 'E os dois rins, e a gordura que está sobre eles, e o que está sobre os lombos, e com os rins tirará o redenho de sobre o fígado,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 10, 'Da maneira que se tira do boi do sacrifício pacífico: e o sacerdote o fará arder sobre o altar do holocausto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 11, 'E o couro do bezerro, e toda sua carne, com sua cabeça, e suas pernas, e seus intestinos, e seu excremento,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 12, 'Em fim, todo o bezerro tirará fora do acampamento, a um lugar limpo, onde se lançam as cinzas, e o queimará ao fogo sobre a lenha: onde se lançam as cinzas será queimado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 13, 'E se toda a congregação de Israel houver errado, e o negócio estiver oculto aos olhos do povo, e houverem feito algo contra algum dos mandamentos do SENHOR em coisas que não se devem fazer, e forem culpados;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 14, 'Logo que for entendido o pecado sobre que transgrediram, a congregação oferecerá um bezerro por expiação, e o trarão diante do tabernáculo do testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 15, 'E os anciãos da congregação porão suas mãos sobre a cabeça do bezerro diante do SENHOR; e em presença do SENHOR degolarão aquele bezerro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 16, 'E o sacerdote ungido meterá do sangue do bezerro no tabernáculo do testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 17, 'E molhará o sacerdote seu dedo no mesmo sangue, e espargirá sete vezes diante do SENHOR até o véu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 18, 'E daquele sangue porá sobre as pontas do altar que está diante do SENHOR no tabernáculo do testemunho, e derramará todo o sangue ao pé do altar do holocausto, que está à porta do tabernáculo do testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 19, 'E lhe tirará toda a gordura, e a fará arder sobre o altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 20, 'E fará daquele bezerro como fez com o bezerro da expiação; o mesmo fará dele: assim fará o sacerdote expiação por eles, e obterão perdão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 21, 'E tirará o bezerro fora do acampamento, e o queimará como queimou o primeiro bezerro; expiação da congregação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 22, 'E quando pecar o príncipe, e fizer por acidente algo contra algum de todos os mandamentos do SENHOR seu Deus, sobre coisas que não se devem fazer, e pecar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 23, 'Logo que lhe for conhecido seu pecado em que transgrediu, apresentará por sua oferta um bode macho sem defeito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 24, 'E porá sua mão sobre a cabeça do bode macho, e o degolará no lugar de onde se degola o holocausto diante do SENHOR; é expiação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 25, 'E tomará o sacerdote com seu dedo do sangue da expiação, e porá sobre as pontas do altar do holocausto, e derramará o sangue ao pé do altar do holocausto:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 26, 'E queimará toda a sua gordura sobre o altar, como a gordura do sacrifício pacífico: assim fará o sacerdote por ele a expiação de seu pecado, e terá perdão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 27, 'E se alguma pessoa comum do povo pecar por acidente, fazendo algo contra algum dos mandamentos do SENHOR em coisas que não se devem fazer, e transgredir;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 28, 'Logo que lhe for conhecido seu pecado que cometeu, trará por sua oferta uma fêmea das cabras, uma cabra sem defeito, por seu pecado que haverá cometido:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 29, 'E porá sua mão sobre a cabeça da expiação, e a degolará no lugar do holocausto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 30, 'Logo tomará o sacerdote em seu dedo de seu sangue, e porá sobre as pontas do altar do holocausto, e derramará todo o seu sangue ao pé do altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 31, 'E lhe tirará toda a sua gordura, da maneira que foi tirada a gordura do sacrifício pacífico; e o sacerdote a fará arder sobre o altar em cheiro suave ao SENHOR: assim fará o sacerdote expiação por ele, e será perdoado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 32, 'E se trouxer cordeiro para sua oferta pelo pecado, fêmea sem defeito trará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 33, 'E porá sua mão sobre a cabeça da expiação, e a degolará por expiação no lugar onde se degola o holocausto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 34, 'Depois tomará o sacerdote com seu dedo do sangue da expiação, e porá sobre as pontas do altar do holocausto; e derramará todo o sangue ao pé do altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 4, 35, 'E lhe tirará toda a sua gordura, como foi tirada a gordura do sacrifício pacífico, e a fará o sacerdote arder no altar sobre a oferta acesa ao SENHOR: e lhe fará o sacerdote expiação de seu pecado que haverá cometido, e será perdoado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 5, 1, 'E quando alguma pessoa pecar, que houver ouvido a voz do que jurou, e ele for testemunha que viu, ou soube, se não o denunciar, ele levará seu pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 5, 2, 'Também a pessoa que houver tocado em qualquer coisa imunda, seja corpo morto de animal selvagem impuro, ou corpo morto de animal doméstico impuro, ou corpo morto de réptil impuro, ainda que não o soubesse, será impura e haverá transgredido:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 5, 3, 'Ou se tocar a homem impuro em qualquer impureza sua de que é impuro, e não o deixar de ver; se depois chega a sabê-lo, será culpável.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 5, 4, 'Também a pessoa que jurar precipitadamente com seus lábios fazer mal ou bem, em quaisquer coisas que o homem profere com juramento, e ele não o conhecer; se depois o entende, será culpado em uma destas coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 5, 5, 'E será que quando pecar em alguma destas coisas, confessará aquilo em que pecou:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 5, 6, 'E para sua expiação trará ao SENHOR por seu pecado que cometeu, uma fêmea dos rebanhos, uma cordeira ou uma cabra como oferta de expiação; e o sacerdote fará expiação por ele de seu pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 5, 7, 'E se não lhe alcançar para um cordeiro, trará em expiação por seu pecado que cometeu, duas rolinhas ou dois pombinhos ao SENHOR; um para expiação, e o outro para holocausto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 5, 8, 'E há de trazê-los ao sacerdote, o qual oferecerá primeiro o que é para expiação, e desunirá sua cabeça de seu pescoço, mas não a separará por completo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 5, 9, 'E espargirá do sangue da expiação sobre a parede do altar; e o que sobrar do sangue o espremerá ao pé do altar; é expiação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 5, 10, 'E do outro fará holocausto conforme o rito; e fará por ele o sacerdote expiação de seu pecado que cometeu, e será perdoado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 5, 11, 'Mas se sua possibilidade não alcançar para duas rolinhas, ou dois pombinhos, o que pecou trará por sua oferta a décima parte de um efa de boa farinha por expiação. Não porá sobre ela azeite, nem sobre ela porá incenso, porque é expiação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 5, 12, 'Ele a trará, pois, ao sacerdote, e o sacerdote tomará dela seu punho cheio, em memória sua, e a fará arder no altar sobre as ofertas acendidas ao SENHOR: é expiação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 5, 13, 'E fará o sacerdote expiação por ele de seu pecado que cometeu em alguma destas coisas, e será perdoado; e o excedente será do sacerdote, como a oferta de alimentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 5, 14, 'Falou mais o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 5, 15, 'Quando alguma pessoa cometer falta, e pecar por acidente nas coisas santificadas ao SENHOR, trará sua expiação ao SENHOR, um carneiro sem mácula dos rebanhos, conforme tua avaliação, em siclos de prata do siclo do santuário, em oferta pelo pecado;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 5, 16, 'E pagará aquilo das coisas santas em que houver pecado, e acrescentará a ele o quinto, e o dará ao sacerdote: e o sacerdote fará expiação por ele com o carneiro do sacrifício pelo pecado, e será perdoado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 5, 17, 'Finalmente, se uma pessoa pecar, ou fizer alguma de todas aquelas coisas que por mandamento do SENHOR não se devem fazer, ainda sem fazê-lo de propósito, é culpável, e levará seu pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 5, 18, 'Trará, pois, ao sacerdote por expiação, segundo tu o estimes, um carneiro sem mácula dos rebanhos: e o sacerdote fará expiação por ele de seu erro que cometeu por ignorância, e será perdoado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 5, 19, 'É infração, e certamente transgrediu contra o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 6, 1, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 6, 2, 'Quando uma pessoa pecar, e fizer transgressão contra o SENHOR, e negar a seu próximo o depositado ou deixado em sua mão, ou roubar, ou extorquir a seu próximo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 6, 3, 'Ou seja que achando o perdido, depois o negar, e jurar em falso, em alguma de todas aquelas coisas em que costuma pecar o homem:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 6, 4, 'Então será que, posto que haverá pecado e ofendido, restituirá aquilo que roubou, ou pelo dano da extorsão, ou o depósito que se lhe depositou, ou o perdido que achou,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 6, 5, 'Ou tudo aquilo sobre que houver jurado falsamente; o restituirá, pois, por inteiro, e acrescentará a ele a quinta parte, que há de pagar a aquele a quem pertence no dia de sua expiação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 6, 6, 'E por sua expiação trará ao SENHOR um carneiro sem mácula dos rebanhos, conforme tua avaliação, ao sacerdote para a expiação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 6, 7, 'E o sacerdote fará expiação por ele diante do SENHOR, e obterá perdão de qualquer de todas as coisas em que costuma ofender.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 6, 8, 'Falou ainda o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 6, 9, 'Manda a Arão e a seus filhos dizendo: Esta é a lei do holocausto: (é holocausto, porque se queima sobre o altar toda a noite até a manhã, e o fogo do altar arderá nele:)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 6, 10, 'O sacerdote se porá sua vestimenta de linho, e se vestirá calções de linho sobre sua carne; e quando o fogo houver consumido o holocausto, apartará ele as cinzas de sobre o altar, e as porá junto ao altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 6, 11, 'Depois se desnudará de suas vestimentas, e se porá outras vestiduras, e tirará as cinzas fora do acampamento ao lugar limpo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 6, 12, 'E o fogo aceso sobre o altar não deverá se apagar, mas o sacerdote porá nele lenha cada manhã, e acomodará sobre ele o holocausto, e queimará sobre ele a gordura pacífica.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 6, 13, 'O fogo deverá arder continuamente no altar; não se apagará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 6, 14, 'E esta é a lei da oferta: os filhos de Arão a oferecerão diante do SENHOR, diante do altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 6, 15, 'E tomará dele um punhado de boa farinha da oferta, e de seu azeite, e todo o incenso que está sobre a oferta de alimentos, e o fará arder sobre o altar por memória, em aroma suavíssimo ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 6, 16, 'E o excedente dela, Arão e seus filhos o comerão; sem levedura se comerá no lugar santo; no átrio do tabernáculo do testemunho o comerão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 6, 17, 'Não se cozerá com levedura: dei-o a eles por sua porção de minhas ofertas acendidas; é coisa santíssima, como a expiação pelo pecado, e como a expiação pela culpa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 6, 18, 'Todos os homens dos filhos de Arão comerão dela. Estatuto perpétuo será para vossas gerações acerca das ofertas acendidas do SENHOR: toda coisa que tocar nelas será santificada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 6, 19, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 6, 20, 'Esta é a oferta de Arão e de seus filhos, que oferecerão ao SENHOR no dia em que forem ungidos: a décima parte de um efa de boa farinha por oferta de alimentos perpétua, a metade à manhã e a metade à tarde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 6, 21, 'Em panela se preparará com azeite; bem misturada a trarás, e os pedaços cozidos da oferta oferecerás ao SENHOR em cheiro suave.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 6, 22, 'E o sacerdote que em lugar de Arão for ungido dentre seus filhos, fará a oferta; estatuto perpétuo do SENHOR: toda ela será queimada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 6, 23, 'E toda a oferta de cereais de sacerdote será inteiramente queimado; não se comerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 6, 24, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 6, 25, 'Fala a Arão e a seus filhos, dizendo: Esta é a lei da expiação: no lugar de onde será degolado o holocausto, será degolada a expiação pelo pecado diante do SENHOR: é coisa santíssima.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 6, 26, 'O sacerdote que a oferecer por expiação, a comerá: no lugar santo será comida, no átrio do tabernáculo do testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 6, 27, 'Tudo o que em sua carne tocar, será santificado; e se cair de seu sangue sobre a roupa, lavarás aquilo sobre que cair, no lugar santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 6, 28, 'E a vasilha de barro em que for cozida, será quebrada: e se for cozida em vasilha de metal, será esfregada e lavada com água.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 6, 29, 'Todo homem dentre os sacerdotes a comerá: é coisa santíssima.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 6, 30, 'Mas não se comerá de expiação alguma, de cujo sangue se meter no tabernáculo do testemunho para reconciliar no santuário: ao fogo será queimada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 1, 'Assim esta é a lei da expiação da culpa: é coisa muito santa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 2, 'No lugar onde degolarem o holocausto, degolarão o sacrifício pela culpa; e espargirá seu sangue em derredor sobre o altar:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 3, 'E dela oferecerá toda a sua gordura, a cauda, e a gordura que cobre os intestinos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 4, 'E os dois rins, e a gordura que está sobre eles, e o que está sobre os lombos; e com os rins tirará o redenho de sobre o fígado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 5, 'E o sacerdote o fará arder sobre o altar; oferta acesa ao SENHOR: é expiação da culpa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 6, 'Todo homem dentre os sacerdotes a comerá: será comida no lugar santo: é coisa muito santa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 7, 'Como a expiação pelo pecado, assim é a expiação da culpa: uma mesma lei terão: será do sacerdote que haverá feito a reconciliação com ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 8, 'E o sacerdote que oferecer holocausto de alguém, o couro do holocausto que oferecer, será para ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 9, 'Também toda oferta de cereais que se cozer em forno, e tudo o que for preparado em panela, ou em frigideira, será do sacerdote que o oferecer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 10, 'E toda oferta de cereais amassada com azeite, e seca, será de todos os filhos de Arão, tanto ao um como ao outro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 11, 'E esta é a lei do sacrifício pacífico, que se oferecerá ao SENHOR:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 12, 'Se se oferecer em ação de graças, oferecerá por sacrifício de ação de graças tortas sem levedura amassadas com azeite, e massas sem levedura untadas com azeite, e boa farinha frita em tortas amassadas com azeite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 13, 'Com tortas de pão levedado oferecerá sua oferta no seu sacrifício pacífico de ação de graças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 14, 'E de toda a oferta apresentará uma parte para oferta elevada ao SENHOR, e será do sacerdote que espargir o sangue das ofertas pacíficas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 15, 'E a carne do sacrifício de suas ofertas pacíficas em ação de graças, se comerá no dia que for oferecida: não deixarão dela nada para outro dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 16, 'Mas se o sacrifício de sua oferta for voto, ou voluntário, no dia que oferecer seu sacrifício será comido; e o que dele restar, será comido no dia seguinte:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 17, 'E o que restar para o terceiro dia da carne do sacrifício, será queimado no fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 18, 'E se se comer da carne do sacrifício de suas pazes no terceiro dia, o que o oferecer não será aceito, nem lhe será imputado; abominação será, e a pessoa que dele comer levará seu pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 19, 'E a carne que tocar a alguma coisa impura, não se comerá; ao fogo será queimada; mas qualquer limpo comerá desta carne.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 20, 'E a pessoa que comer a carne do sacrifício pacífico, o qual é do SENHOR, estando impura, aquela pessoa será eliminada de seus povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 21, 'Além disso, a pessoa que tocar alguma coisa impura, em impureza de homem, ou em animal impuro, ou em qualquer abominação impura, e comer a carne do sacrifício pacífico, o qual é do SENHOR, aquela pessoa será eliminada de seus povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 22, 'Falou ainda o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 23, 'Fala aos filhos de Israel, dizendo: Nenhuma gordura de boi, nem de cordeiro, nem de cabra, comereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 24, 'A gordura de animal morto naturalmente, e a gordura do que foi arrebatado de feras, se preparará para qualquer outro uso, mas não o comereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 25, 'Porque qualquer um que comer gordura de animal, do qual se oferece ao SENHOR oferta acesa, a pessoa que o comer, será cortada de seus povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 26, 'Além disso, nenhum sangue comereis em todas as vossas habitações, tanto de aves como de animais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 27, 'Qualquer um pessoa que comer algum sangue, a tal pessoa será eliminada de seus povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 28, 'Falou mais o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 29, 'Fala aos filhos de Israel, dizendo: O que oferecer sacrifício de suas pazes ao SENHOR, trará sua oferta do sacrifício de suas pazes ao SENHOR;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 30, 'Suas mãos trarão as ofertas que se hão de queimar ao SENHOR: trará a gordura com o peito: o peito para que este seja movido, como sacrifício movido diante do SENHOR;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 31, 'E a gordura a fará arder o sacerdote no altar, mas o peito será de Arão e de seus filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 32, 'E dareis ao sacerdote para ser elevada em oferta, a coxa direita dos sacrifícios de vossas pazes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 33, 'O que dos filhos de Arão oferecer o sangue das ofertas pacíficas, e a gordura, dele será em porção a coxa direita;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 34, 'Porque tomei dos filhos de Israel, dos sacrifícios de suas ofertas pacíficas, o peito que é movido, e a coxa elevada em oferta, e o dei a Arão o sacerdote e a seus filhos, por estatuto perpétuo dos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 35, 'Esta é pela unção de Arão e a unção de seus filhos, a parte deles nas ofertas acendidas ao SENHOR, desde o dia que ele os apresentou para serem sacerdotes do SENHOR:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 36, 'O qual mandou o SENHOR que lhes dessem, desde o dia que ele os ungiu dentre os filhos de Israel, por estatuto perpétuo em suas gerações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 37, 'Esta é a lei do holocausto, da oferta, da expiação pelo pecado, e da culpa, e das consagrações, e do sacrifício pacífico:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 7, 38, 'A qual intimou o SENHOR a Moisés, no monte Sinai, no dia que mandou aos filhos de Israel que oferecessem suas ofertas ao SENHOR no deserto de Sinai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 1, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 2, 'Toma a Arão e a seus filhos com ele, e as vestimentas, e o azeite da unção, e o bezerro da expiação, e os dois carneiros, e o cesto dos pães ázimos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 3, 'E reúne toda a congregação à porta do tabernáculo do testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 4, 'Fez, pois, Moisés como o SENHOR lhe mandou, e juntou-se a congregação à porta do tabernáculo do testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 5, 'E disse Moisés à congregação: Isto é o que o SENHOR mandou fazer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 6, 'Então Moisés fez chegar a Arão e a seus filhos, e lavou-os com água.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 7, 'E pôs sobre ele a túnica, e cingiu-o com o cinto; vestiu-lhe depois o manto, e pôs sobre ele o éfode, e cingiu-o com o cinto do éfode, e ajustou-o com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 8, 'Pôs-lhe logo encima o peitoral, e nele pôs o Urim e Tumim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 9, 'Depois pôs a mitra sobre sua cabeça; e sobre a mitra em sua frente dianteira pôs a placa de ouro, a coroa santa; como o SENHOR havia mandado a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 10, 'E tomou Moisés o azeite da unção, e ungiu o tabernáculo, e todas as coisas que estavam nele, e santificou-as.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 11, 'E espargiu dele sobre o altar sete vezes, e ungiu o altar e todos os seus utensílios, e a pia e sua base, para santificá-los.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 12, 'E derramou do azeite da unção sobre a cabeça de Arão, e ungiu-o para santificá-lo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 13, 'Depois Moisés fez chegar os filhos de Arão, e vestiu-lhes as túnicas, e cingiu-os com cintos, e ajustou-lhes as tiaras), como o SENHOR o havia mandado a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 14, 'Fez logo chegar o bezerro da expiação, e Arão e seus filhos puseram suas mãos sobre a cabeça do bezerro da expiação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 15, 'E degolou-o; e Moisés tomou o sangue, e pôs com seu dedo sobre as pontas do altar ao redor, e purificou o altar; e lançou o resto do sangue ao pé do altar, e santificou-o para fazer reconciliação sobre ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 16, 'Depois tomou toda a gordura que estava sobre os intestinos, e o redenho do fígado, e os dois rins, e a gordura deles, e o fez Moisés arder sobre o altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 17, 'Mas o bezerro, e seu couro, e sua carne, e seu excremento, queimou-o ao fogo fora do acampamento; como o SENHOR o havia mandado a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 18, 'Depois fez chegar o carneiro do holocausto, e Arão e seus filhos puseram suas mãos sobre a cabeça do carneiro:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 19, 'E degolou-o; e espargiu Moisés o sangue sobre o altar em derredor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 20, 'E cortou o carneiro em pedaços; e Moisés fez arder a cabeça, e os pedaços, e a gordura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 21, 'Lavou logo com água os intestinos e pernas, e queimou Moisés todo o carneiro sobre o altar: holocausto em cheiro suave, oferta acesa ao SENHOR; como o havia o SENHOR mandado a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 22, 'Depois fez chegar o outro carneiro, o carneiro das consagrações, e Arão e seus filhos puseram suas mãos sobre a cabeça do carneiro:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 23, 'E degolou-o; e tomou Moisés de seu sangue, e pôs sobre a ponta da orelha direita de Arão, e sobre o dedo polegar de sua mão direita, e sobre o dedo polegar de seu pé direito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 24, 'Fez chegar logo os filhos de Arão, e pôs Moisés do sangue sobre a ponta de suas orelhas direitas, e sobre os polegares de suas mãos direitas, e sobre os polegares de seus pés direitos: e espargiu Moisés o sangue sobre o altar em derredor;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 25, 'E depois tomou a gordura, e a cauda, e toda a gordura que estava sobre os intestinos, e o redenho do fígado, e os dois rins, e a gordura deles, e a coxa direita;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 26, 'E do cesto dos pães ázimos, que estava diante do SENHOR, tomou uma torta sem levedura, e uma torta de pão de azeite, e um bolo, e o pôs com a gordura e com a coxa direita;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 27, 'E o pôs tudo nas mãos de Arão, e nas mãos de seus filhos, e o fez mover: oferta agitada diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 28, 'Depois tomou aquelas coisas Moisés das mãos deles, e as fez arder no altar sobre o holocausto: as consagrações em cheiro suave, oferta acesa ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 29, 'E tomou Moisés o peito, e moveu-o, oferta movida diante do SENHOR: do carneiro das consagrações aquela foi a parte de Moisés; como o SENHOR o havia mandado a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 30, 'Logo tomou Moisés do azeite da unção, e do sangue que estava sobre o altar, e espargiu sobre Arão, e sobre suas vestiduras, sobre seus filhos, e sobre as vestiduras de seus filhos com ele; e santificou a Arão, e suas vestiduras, e a seus filhos, e as vestiduras de seus filhos com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 31, 'E disse Moisés a Arão e a seus filhos: Comei a carne à porta do tabernáculo do testemunho; e comei-a ali com o pão que está no cesto das consagrações, segundo eu mandei, dizendo: Arão e seus filhos a comerão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 32, 'E o que sobrar da carne e do pão, queimareis ao fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 33, 'Da porta do tabernáculo do testemunho não saireis em sete dias, até o dia que se cumprirem os dias de vossas consagrações: porque por sete dias sereis consagrados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 34, 'Da maneira que hoje se fez, mandou fazer o SENHOR para expiar-vos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 35, 'À porta, pois, do tabernáculo do testemunho estareis dia e noite por sete dias, e guardareis a ordenança diante do SENHOR, para que não morrais; porque assim me foi mandado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 8, 36, 'E Arão e seus filhos fizeram todas as coisas que mandou o SENHOR por meio de Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 9, 1, 'E foi no dia oitavo, que Moisés chamou a Arão e a seus filhos, e aos anciãos de Israel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 9, 2, 'E disse a Arão: Toma das vacas um bezerro para expiação, e um carneiro para holocausto, sem defeito, e oferece-os diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 9, 3, 'E aos filhos de Israel falarás, dizendo: Tomai um bode macho para expiação, e um bezerro e um cordeiro de ano, sem mácula, para holocausto;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 9, 4, 'Também um boi e um carneiro para sacrifício pacífico, que imoleis diante do SENHOR; e uma oferta de cereais amassada com azeite: porque o SENHOR se aparecerá hoje a vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 9, 5, 'E levaram o que mandou Moisés diante do tabernáculo do testemunho, e chegou-se toda a congregação, e puseram-se diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 9, 6, 'Então Moisés disse: Isto é o que mandou o SENHOR; fazei-o, e a glória do SENHOR se vos aparecerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 9, 7, 'E disse Moisés a Arão: Achega-te ao altar, e faze tua expiação, e teu holocausto, e faze a reconciliação por ti e pelo povo: faze também a oferta do povo, e faze a reconciliação por eles; como mandou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 9, 8, 'Então chegou-se Arão ao altar; e degolou seu bezerro da expiação que era por ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 9, 9, 'E os filhos de Arão lhe trouxeram o sangue; e ele molhou seu dedo no sangue, e pôs sobre as pontas do altar, e derramou o resto do sangue ao pé do altar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 9, 10, 'E a gordura e rins e redenho do fígado, da expiação, os fez arder sobre o altar; como o SENHOR o havia mandado a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 9, 11, 'Mas a carne e o couro os queimou ao fogo fora do acampamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 9, 12, 'Degolou também o holocausto, e os filhos de Arão lhe apresentaram o sangue, a qual espargiu ele ao redor sobre o altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 9, 13, 'Apresentaram-lhe depois o holocausto, em pedaços, e a cabeça; e os fez queimar sobre o altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 9, 14, 'Logo lavou os intestinos e as pernas, e queimou-os sobre o holocausto no altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 9, 15, 'Ofereceu também a oferta do povo, e tomou o bode macho que era para a expiação do povo, e degolou-o, e o ofereceu pelo pecado como o primeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 9, 16, 'E ofereceu o holocausto, e fez segundo o rito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 9, 17, 'Ofereceu também a oferta de cereais, e encheu dela sua mão, e o fez queimar sobre o altar, também do holocausto da manhã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 9, 18, 'Degolou também o boi e o carneiro em sacrifício pacífico, que era do povo: e os filhos de Arão lhe apresentaram o sangue (o qual espargiu ele sobre o altar ao redor),'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 9, 19, 'E a gordura do boi; e do carneiro a cauda com o que cobre as entranhas, e os rins, e o redenho do fígado:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 9, 20, 'E puseram a gordura sobre os peitos, e ele queimou a gordura sobre o altar:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 9, 21, 'Porém os peitos, com a coxa direita, moveu-os Arão por oferta movida diante do SENHOR; como o SENHOR o havia mandado a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 9, 22, 'Depois levantou Arão suas mãos até o povo e abençoou-os: e desceu de fazer a expiação, e o holocausto, e o sacrifício pacífico.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 9, 23, 'E entraram Moisés e Arão no tabernáculo do testemunho; e saíram, e bendisseram ao povo: e a glória do SENHOR se apareceu a todo o povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 9, 24, 'E saiu fogo de diante do SENHOR, e consumiu o holocausto e a gordura sobre o altar; e vendo-o todo o povo, louvaram, e caíram sobre seus rostos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 10, 1, 'E os filhos de Arão, Nadabe e Abiú, tomaram cada um seu incensário, e puseram fogo neles, sobre o qual puseram incenso, e ofereceram diante do SENHOR fogo estranho, que ele nunca lhes mandou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 10, 2, 'E saiu fogo de diante do SENHOR que os queimou, e morreram diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 10, 3, 'Então disse Moisés a Arão: Isto é o que falou o SENHOR, dizendo: Em meus achegados me santificarei, e em presença de todo o povo serei glorificado. E Arão calou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 10, 4, 'E chamou Moisés a Misael, e a Elzafã, filhos de Uziel, tio de Arão, e disse-lhes: Achegai-vos e tirai a vossos irmãos de diante do santuário fora do acampamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 10, 5, 'E eles chegaram, e tiraram-nos com suas túnicas fora do acampamento, como disse Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 10, 6, 'Então Moisés disse a Arão, e a Eleazar e a Itamar, seus filhos: Não descubrais vossas cabeças, nem rasgueis vossas roupas, para que não morrais, nem se levante a ira sobre toda a congregação: porém vossos irmãos, toda a casa de Israel, lamentarão o incêndio que o SENHOR fez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 10, 7, 'Nem saireis da porta do tabernáculo do testemunho, porque morrereis; porquanto o azeite da unção do SENHOR está sobre vós. E eles fizeram conforme o dito de Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 10, 8, 'E o SENHOR falou a Arão, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 10, 9, 'Tu, e teus filhos contigo, não bebereis vinho nem bebida forte, quando houverdes de entrar no tabernáculo do testemunho, para que não morrais: estatuto perpétuo por vossas gerações;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 10, 10, 'E para poder discernir entre o santo e o profano, e entre o impuro e o limpo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 10, 11, 'E para ensinar aos filhos de Israel todos os estatutos que o SENHOR lhes disse por meio de Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 10, 12, 'E Moisés disse a Arão, e a Eleazar e a Itamar, seus filhos que haviam restado: Tomai a oferta de cereais que resta das ofertas acendidas ao SENHOR, e comei-a sem levedura junto ao altar, porque é coisa muito santa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 10, 13, 'Haveis, pois, de comê-la no lugar santo: porque isto é estatuto para ti, e estatuto para teus filhos, das ofertas acendidas ao SENHOR, pois que assim me foi mandado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 10, 14, 'Comereis também em lugar limpo, tu e teus filhos e tuas filhas contigo, o peito da oferta movida, e a coxa elevada, porque por estatuto para ti, e estatuto para teus filhos, são dados dos sacrifícios das ofertas pacíficas dos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 10, 15, 'Com as ofertas das gorduras que se hão de acender, trarão a coxa que se há de elevar, e o peito que será movido, para que o movas por oferta movida diante do SENHOR: e será por estatuto perpétuo teu, e de teus filhos contigo, como o SENHOR o mandou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 10, 16, 'E Moisés mandou o bode macho da expiação, e achou-se que era queimado: e irou-se contra Eleazar e Itamar, os filhos de Arão que haviam restado, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 10, 17, 'Por que não comestes a expiação no lugar santo? Porque é muito santa, e deu-a ele a vós para levar a iniquidade da congregação, para que sejam reconciliados diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 10, 18, 'Vedes que seu sangue não foi metido dentro do santuário: havíeis de comê-la no lugar santo, como eu mandei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 10, 19, 'E respondeu Arão a Moisés: Eis que hoje ofereceram sua expiação e seu holocausto diante do SENHOR: mas me aconteceram estas coisas: pois se comesse eu hoje da expiação, Teria sido aceito ao SENHOR?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 10, 20, 'E quando Moisés ouviu isto, deu-se por satisfeito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 1, 'E falou o SENHOR a Moisés e a Arão, dizendo-lhes:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 2, 'Falai aos filhos de Israel, dizendo: Estes são os animais que comereis de todos os animais que estão sobre a terra.')
